//! How a surface takes the light: a colour, optional textures, and the
//! shading values `scene.wgsl` reads (roughness, sheen, translucency,
//! opacity). Fabrics get theirs from [`for_fabric`], with textures
//! generated by code from the weave or knit: colour, and a detail map of
//! surface normals plus roughness, so threads catch the light as threads.
//!
//! Everything here is plain CPU data (pixels in a `Vec<u8>`);
//! [`crate::gpu::Renderer`] uploads a [`TextureImage`] to the GPU, caching
//! by its `id` so the same fabric's texture isn't re-uploaded every frame.

use std::collections::HashMap;
use std::f32::consts::PI;
use std::sync::{Arc, Mutex, OnceLock};

use od_core::document::{Fabric, FabricTexture, Pattern};

use crate::scene::{srgb_to_linear, Color};

/// An RGBA8 image, straight (non-premultiplied) alpha. `id` is a stable
/// identity for the renderer's texture cache: two [`TextureImage`]s with
/// the same `id` are assumed to be the same pixels, so generate it once per
/// distinct texture (e.g. per fabric) and reuse it, rather than minting a
/// fresh one every frame.
#[derive(Debug, Clone, PartialEq)]
pub struct TextureImage {
    pub id: u64,
    pub width: u32,
    pub height: u32,
    /// `width * height * 4` bytes, row-major, top to bottom.
    pub rgba: Vec<u8>,
}

/// The shading values of a surface, besides its colour.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Surface {
    /// Microfacet roughness, 0..1.
    pub roughness: f32,
    /// Linear-light colour of the sheen lobe (glow of fibres at grazing
    /// angles); black for none.
    pub sheen: [f32; 3],
    /// How tightly the sheen hugs the silhouette, 0..1.
    pub sheen_roughness: f32,
    /// Light let through from behind, 0..1.
    pub translucency: f32,
    /// 1 opaque; less covers only part of each pixel, so what's behind
    /// shows through without sorting.
    pub opacity: f32,
    /// How strongly the detail map's normals tilt the surface.
    pub normal_strength: f32,
}

impl Default for Surface {
    /// Matte and opaque: skin, or a fabric with no look of its own.
    fn default() -> Self {
        Self {
            roughness: 0.7,
            sheen: [0.0; 3],
            sheen_roughness: 0.5,
            translucency: 0.0,
            opacity: 1.0,
            normal_strength: 1.0,
        }
    }
}

/// A surface's appearance.
#[derive(Debug, Clone, PartialEq)]
pub struct Material {
    /// Linear-light RGBA, as in [`crate::scene::Color`] elsewhere: the
    /// colour of an untextured surface, and the overall colour of a
    /// textured one where it's drawn flat (see-through, wireframe).
    pub base_color: Color,
    /// The colour, in sRGB; replaces `base_color` where it's drawn.
    pub texture: Option<Arc<TextureImage>>,
    /// Surface detail: RGB a tangent-space normal (x along the texture's
    /// width, y down its height), A a roughness scale, 128 for ×1.
    pub detail: Option<Arc<TextureImage>>,
    pub surface: Surface,
    /// How many millimetres of the pattern one copy of the textures spans.
    pub repeat_mm: f32,
    /// The grainline, as [`Pattern::grain_angle`]: the textures' height
    /// runs along it.
    pub grain_degrees: f32,
}

impl Material {
    /// A flat tint, no texture.
    pub fn flat(base_color: Color) -> Self {
        Self {
            base_color,
            texture: None,
            detail: None,
            surface: Surface::default(),
            repeat_mm: 1000.0,
            grain_degrees: 0.0,
        }
    }

    pub fn textured(base_color: Color, texture: Arc<TextureImage>) -> Self {
        Self {
            texture: Some(texture),
            ..Self::flat(base_color)
        }
    }

    /// The vertex colour a draw of this material is given: the shader
    /// multiplies it with the texture, which carries the colour itself.
    pub fn vertex_color(&self) -> Color {
        match self.texture {
            Some(_) => [1.0, 1.0, 1.0, self.base_color[3]],
            None => self.base_color,
        }
    }
}

/// How many repeats of the weave one generated texture holds across, so
/// thread-to-thread variation doesn't tile every repeat.
pub const REPEATS: u32 = 4;
/// Generated textures' width and height in pixels.
const SIZE: u32 = 256;

/// A fabric's material: colour, generated weave textures and shading
/// from its [`od_core::document::FabricLook`]. Textures are made once per
/// weave and colour and shared after that.
pub fn for_fabric(fabric: &Fabric) -> Material {
    let base = linear_rgb(fabric.color);
    let look = &fabric.look;
    let maps = fabric_maps(fabric.texture, fabric.color);
    let tint = look.sheen_tint.clamp(0.0, 1.0);
    let sheen = base.map(|c| (1.0 + (c - 1.0) * tint) * look.sheen.max(0.0));
    Material {
        base_color: [base[0], base[1], base[2], 1.0],
        texture: Some(maps.0),
        detail: Some(maps.1),
        surface: Surface {
            roughness: look.roughness.clamp(0.02, 1.0),
            sheen,
            sheen_roughness: look.sheen_roughness.clamp(0.05, 1.0),
            translucency: look.translucency.clamp(0.0, 1.0),
            opacity: look.opacity.clamp(0.05, 1.0),
            normal_strength: normal_strength(fabric.texture),
        },
        repeat_mm: look.repeat_mm.max(0.05) * REPEATS as f32,
        grain_degrees: 0.0,
    }
}

/// [`for_fabric`] for `pattern`'s fabric, laid along its grainline.
pub fn for_pattern(pattern: &Pattern) -> Material {
    Material {
        grain_degrees: pattern.grain_angle,
        ..for_fabric(&pattern.fabric)
    }
}

fn normal_strength(texture: FabricTexture) -> f32 {
    match texture {
        FabricTexture::Flat => 0.3,
        FabricTexture::Satin => 0.5,
        FabricTexture::Velvet => 0.4,
        _ => 1.0,
    }
}

fn linear_rgb([r, g, b]: [u8; 3]) -> [f32; 3] {
    [srgb_to_linear(r), srgb_to_linear(g), srgb_to_linear(b)]
}

fn linear_to_srgb(c: f32) -> u8 {
    let c = c.clamp(0.0, 1.0);
    let s = if c <= 0.003_130_8 {
        c * 12.92
    } else {
        1.055 * c.powf(1.0 / 2.4) - 0.055
    };
    (s * 255.0 + 0.5) as u8
}

type Maps = (Arc<TextureImage>, Arc<TextureImage>);
type MapCache = Mutex<HashMap<(FabricTexture, [u8; 3]), Maps>>;

/// The colour and detail textures for a weave in a colour, cached.
fn fabric_maps(texture: FabricTexture, color: [u8; 3]) -> Maps {
    static CACHE: OnceLock<MapCache> = OnceLock::new();
    let cache = CACHE.get_or_init(Default::default);
    if let Some(maps) = cache
        .lock()
        .ok()
        .and_then(|c| c.get(&(texture, color)).cloned())
    {
        return maps;
    }
    let id = fnv(&format!("{}/{color:?}", texture.name()));
    let (albedo, detail) = weave(texture, color, id);
    let maps = (Arc::new(albedo), Arc::new(detail));
    if let Ok(mut c) = cache.lock() {
        c.insert((texture, color), maps.clone());
    }
    maps
}

/// FNV-1a: a stable texture id from a description of its pixels.
fn fnv(key: &str) -> u64 {
    key.bytes().fold(0xcbf2_9ce4_8422_2325_u64, |h, b| {
        (h ^ u64::from(b)).wrapping_mul(0x0100_0000_01b3)
    })
}

/// One generated pixel: height of the cloth surface (0 deep in a gap,
/// 1 on top of a yarn), linear colour, and a roughness scale.
#[derive(Clone, Copy)]
struct Texel {
    height: f32,
    color: [f32; 3],
    roughness: f32,
}

/// The colour and detail textures of `texture` in `color`, [`REPEATS`]
/// repeats across, tiling seamlessly. Ids are `id` and `id + 1`.
pub fn weave(texture: FabricTexture, color: [u8; 3], id: u64) -> (TextureImage, TextureImage) {
    let base = linear_rgb(color);
    let per_repeat = (SIZE / REPEATS) as f32;
    let mut texels = Vec::with_capacity((SIZE * SIZE) as usize);
    for y in 0..SIZE {
        for x in 0..SIZE {
            let (u, v) = ((x as f32 + 0.5) / per_repeat, (y as f32 + 0.5) / per_repeat);
            texels.push(texel(texture, base, u, v));
        }
    }
    // Yarn about as tall as it is wide: a structure of n threads per
    // repeat stands 1/(2n) of a repeat high.
    let depth = match texture {
        FabricTexture::Plain | FabricTexture::Flat => 0.25,
        FabricTexture::Twill => 0.125,
        FabricTexture::Satin => 0.1,
        FabricTexture::Jersey | FabricTexture::Rib => 0.25,
        FabricTexture::Velvet => 0.02,
    };
    images(&texels, SIZE, depth * per_repeat, id)
}

/// The two images from generated texels; `depth` is how many pixels tall
/// a height of 1 stands.
fn images(texels: &[Texel], size: u32, depth: f32, id: u64) -> (TextureImage, TextureImage) {
    let at = |x: i64, y: i64| {
        let s = size as i64;
        texels[(y.rem_euclid(s) * s + x.rem_euclid(s)) as usize]
    };
    let mut albedo = Vec::with_capacity(texels.len() * 4);
    let mut detail = Vec::with_capacity(texels.len() * 4);
    for y in 0..size as i64 {
        for x in 0..size as i64 {
            let t = at(x, y);
            albedo.extend(t.color.map(linear_to_srgb));
            albedo.push(255);
            let sx = (at(x + 1, y).height - at(x - 1, y).height) * depth / 2.0;
            let sy = (at(x, y + 1).height - at(x, y - 1).height) * depth / 2.0;
            let n = glam::Vec3::new(-sx, -sy, 1.0).normalize();
            detail.extend(n.to_array().map(|c| ((c * 0.5 + 0.5) * 255.0 + 0.5) as u8));
            detail.push((t.roughness.clamp(0.0, 2.0) * 127.5 + 0.5) as u8);
        }
    }
    let image = |id, rgba| TextureImage {
        id,
        width: size,
        height: size,
        rgba,
    };
    (image(id, albedo), image(id.wrapping_add(1), detail))
}

/// A hash of integer coordinates, 0..1.
fn hash(x: i32, y: i32, seed: u32) -> f32 {
    let mut h = (x as u32).wrapping_mul(0x8da6_b343)
        ^ (y as u32).wrapping_mul(0xd816_3841)
        ^ seed.wrapping_mul(0xcb1a_b31f);
    h ^= h >> 13;
    h = h.wrapping_mul(0x5bd1_e995);
    h ^= h >> 15;
    (h & 0xffff) as f32 / 65535.0
}

/// Smooth value noise with `cells` cells per texture, wrapping round.
fn noise(u: f32, v: f32, cells: i32, seed: u32) -> f32 {
    let scale = cells as f32 / REPEATS as f32;
    let (x, y) = (u * scale, v * scale);
    let (x0, y0) = (x.floor(), y.floor());
    let (fx, fy) = (x - x0, y - y0);
    let s = |t: f32| t * t * (3.0 - 2.0 * t);
    let (sx, sy) = (s(fx), s(fy));
    let h = |i: i32, j: i32| hash(i.rem_euclid(cells), j.rem_euclid(cells), seed);
    let (i, j) = (x0 as i32, y0 as i32);
    let top = h(i, j) + (h(i + 1, j) - h(i, j)) * sx;
    let bottom = h(i, j + 1) + (h(i + 1, j + 1) - h(i, j + 1)) * sx;
    top + (bottom - top) * sy
}

/// Height across a round yarn, `d` 0..1 from one edge to the other.
fn round(d: f32) -> f32 {
    let r = 2.0 * d - 1.0;
    (1.0 - r * r).max(0.0).sqrt()
}

fn scaled(c: [f32; 3], k: f32) -> [f32; 3] {
    c.map(|c| c * k)
}

fn mixed(a: [f32; 3], b: [f32; 3], t: f32) -> [f32; 3] {
    [0, 1, 2].map(|i| a[i] + (b[i] - a[i]) * t)
}

/// The texel at (`u`, `v`) in repeats; `v` runs along the grain (warp).
fn texel(texture: FabricTexture, base: [f32; 3], u: f32, v: f32) -> Texel {
    match texture {
        FabricTexture::Flat => woven(2, |i, j| (i + j) % 2 == 0, base, base, u, v, 0.95),
        FabricTexture::Plain => {
            let weft = scaled(base, 1.04);
            woven(2, |i, j| (i + j) % 2 == 0, base, weft, u, v, 1.0)
        }
        // 3/1 twill: the warp over three, under one, a step on each row,
        // so diagonals run across; the paler weft shows between, as in
        // denim.
        FabricTexture::Twill => {
            let weft = mixed(base, [0.75, 0.74, 0.7], 0.45);
            woven(4, |i, j| (i + j) % 4 != 3, base, weft, u, v, 1.0)
        }
        // Five-harness satin: the weft comes up once in five, two along
        // on each row, so the face is long warp floats.
        FabricTexture::Satin => woven(5, |i, j| j != (2 * i) % 5, base, base, u, v, 0.7),
        FabricTexture::Jersey => knit(base, u, v),
        FabricTexture::Rib => {
            let t = knit(base, u, v);
            // 1×1 rib: every other column of loops sinks back.
            if (u * 2.0).rem_euclid(2.0) < 1.0 {
                Texel {
                    height: 0.35 + 0.65 * t.height,
                    ..t
                }
            } else {
                Texel {
                    height: 0.25 * t.height,
                    color: scaled(t.color, 0.82),
                    roughness: 1.15,
                }
            }
        }
        FabricTexture::Velvet => {
            let fine = noise(u, v, 128, 7);
            let crush = noise(u, v, 12, 9);
            Texel {
                height: 0.6 * fine + 0.4 * crush,
                color: scaled(base, 0.9 + 0.2 * crush),
                roughness: 1.0,
            }
        }
    }
}

/// A woven structure of `n`×`n` cells per repeat: in column `i`, row `j`
/// the warp (running along `v`) is on top if `warp_up(i, j)`, otherwise
/// the weft. Each float arches over its length; the gaps between yarns
/// are dark and rough. `top_roughness` scales roughness on the floats.
fn woven(
    n: u32,
    warp_up: impl Fn(u32, u32) -> bool,
    warp: [f32; 3],
    weft: [f32; 3],
    u: f32,
    v: f32,
    top_roughness: f32,
) -> Texel {
    let (cu, cv) = (u * n as f32, v * n as f32);
    let (gi, gj) = (cu.floor() as i32, cv.floor() as i32);
    let (du, dv) = (cu - gi as f32, cv - gj as f32);
    let (i, j) = (
        gi.rem_euclid(n as i32) as u32,
        gj.rem_euclid(n as i32) as u32,
    );
    let on_top = warp_up(i, j);
    // The float's extent along its yarn: cells in a row with the same
    // yarn on top.
    let same = |k: i32| {
        let (ci, cj) = if on_top { (i as i32, k) } else { (k, j as i32) };
        warp_up(
            ci.rem_euclid(n as i32) as u32,
            cj.rem_euclid(n as i32) as u32,
        ) == on_top
    };
    let (here, along_d) = if on_top {
        (j as i32, dv)
    } else {
        (i as i32, du)
    };
    let mut start = here;
    while same(start - 1) && here - start < n as i32 - 1 {
        start -= 1;
    }
    let mut end = here;
    while same(end + 1) && end - start < n as i32 - 1 {
        end += 1;
    }
    let t = (here - start) as f32 + along_d;
    let length = (end - start + 1) as f32;
    let arch = (PI * t / length).sin().max(0.0).sqrt();
    let across = round(if on_top { du } else { dv });
    let height = across * (0.35 + 0.65 * arch);
    // Each yarn a little lighter or darker than the next, and slubbed
    // along its length.
    let (yarn, pos) = if on_top { (gi, cv) } else { (gj, cu) };
    let seed = if on_top { 1 } else { 2 };
    let slub = noise(
        if on_top {
            yarn as f32 / n as f32
        } else {
            pos / n as f32
        },
        if on_top {
            pos / n as f32
        } else {
            yarn as f32 / n as f32
        },
        64,
        seed + 10,
    );
    let shade = 0.94 + 0.08 * hash(yarn, 0, seed) + 0.06 * (slub - 0.5);
    let color = if on_top { warp } else { weft };
    Texel {
        height,
        color: scaled(color, shade * (0.72 + 0.28 * height)),
        roughness: 1.3 - (1.3 - top_roughness) * height,
    }
}

/// A knit's face: two columns (wales) of V-shaped loops per repeat, two
/// rows (courses) down it.
fn knit(base: [f32; 3], u: f32, v: f32) -> Texel {
    let (cu, cv) = (u * 2.0, v * 2.0);
    let (gi, gj) = (cu.floor() as i32, cv.floor() as i32);
    let (du, dv) = (cu - gi as f32, cv - gj as f32);
    // Each loop's two legs lean in to meet at the bottom of the V.
    let leg = |side: f32| {
        let centre = 0.5 + side * (0.08 + 0.3 * (1.0 - dv));
        let d = (du - centre).abs() / 0.24;
        round((d + 1.0) / 2.0)
    };
    let along = 0.55 + 0.45 * (PI * dv).sin();
    let height = leg(-1.0).max(leg(1.0)) * along;
    let shade = 0.95 + 0.08 * hash(gi, 0, 3) + 0.04 * hash(gi, gj, 4);
    Texel {
        height,
        color: scaled(base, shade * (0.7 + 0.3 * height)),
        roughness: 1.25 - 0.3 * height,
    }
}

/// A colour and a detail texture from a photo of a fabric (straight sRGB
/// RGBA, `width`×`height`): the photo itself as colour, and its
/// brightness taken as height, so light threads stand up from dark gaps,
/// and as smoothness. Ids are `id` and `id + 1`.
pub fn maps_from_photo(
    id: u64,
    width: u32,
    height: u32,
    rgba: &[u8],
) -> (TextureImage, TextureImage) {
    let (w, h) = (width.max(1), height.max(1));
    let luminance: Vec<f32> = rgba
        .chunks_exact(4)
        .map(|p| {
            0.2126 * srgb_to_linear(p[0])
                + 0.7152 * srgb_to_linear(p[1])
                + 0.0722 * srgb_to_linear(p[2])
        })
        .collect();
    let (lo, hi) = luminance
        .iter()
        .fold((f32::MAX, f32::MIN), |(l, h), &v| (l.min(v), h.max(v)));
    let range = (hi - lo).max(1e-4);
    let at = |x: i64, y: i64| {
        let (x, y) = (x.rem_euclid(w as i64), y.rem_euclid(h as i64));
        (luminance[(y * w as i64 + x) as usize] - lo) / range
    };
    let mut detail = Vec::with_capacity((w * h * 4) as usize);
    for y in 0..h as i64 {
        for x in 0..w as i64 {
            // Sobel: the slope of the brightness, as if it were height.
            let sx = (at(x + 1, y - 1) + 2.0 * at(x + 1, y) + at(x + 1, y + 1))
                - (at(x - 1, y - 1) + 2.0 * at(x - 1, y) + at(x - 1, y + 1));
            let sy = (at(x - 1, y + 1) + 2.0 * at(x, y + 1) + at(x + 1, y + 1))
                - (at(x - 1, y - 1) + 2.0 * at(x, y - 1) + at(x + 1, y - 1));
            let n = glam::Vec3::new(-sx, -sy, 2.0).normalize();
            detail.extend(n.to_array().map(|c| ((c * 0.5 + 0.5) * 255.0 + 0.5) as u8));
            // Brighter (raised) is smoother: roughness ×1.3 down to ×0.7.
            let rough = 1.3 - 0.6 * at(x, y);
            detail.push((rough * 127.5 + 0.5) as u8);
        }
    }
    let mut albedo = rgba.to_vec();
    albedo.resize((w * h * 4) as usize, 255);
    (
        TextureImage {
            id,
            width: w,
            height: h,
            rgba: albedo,
        },
        TextureImage {
            id: id.wrapping_add(1),
            width: w,
            height: h,
            rgba: detail,
        },
    )
}

/// What a texture's pixels hold, for averaging them into smaller mips.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TexelKind {
    /// sRGB colour, averaged in linear light.
    Color,
    /// A [`Material::detail`] map: normals averaged and renormalised, the
    /// roughness raised where they disagree, as bumps too small to see
    /// make a surface look rougher.
    Detail,
}

/// Successively halved copies of an image down to 1×1, the image itself
/// first: (width, height, RGBA8).
pub fn mip_chain(
    width: u32,
    height: u32,
    rgba: &[u8],
    kind: TexelKind,
) -> Vec<(u32, u32, Vec<u8>)> {
    let mut chain = vec![(width.max(1), height.max(1), rgba.to_vec())];
    loop {
        let (w, h, prev) = chain.last().expect("never empty");
        let (w, h) = (*w, *h);
        if w == 1 && h == 1 {
            break;
        }
        let (nw, nh) = ((w / 2).max(1), (h / 2).max(1));
        let mut next = Vec::with_capacity((nw * nh * 4) as usize);
        for y in 0..nh {
            for x in 0..nw {
                let pixels: Vec<&[u8]> = [(0, 0), (1, 0), (0, 1), (1, 1)]
                    .iter()
                    .map(|&(dx, dy)| {
                        let (sx, sy) = ((2 * x + dx).min(w - 1), (2 * y + dy).min(h - 1));
                        let i = ((sy * w + sx) * 4) as usize;
                        &prev[i..i + 4]
                    })
                    .collect();
                next.extend(average(&pixels, kind));
            }
        }
        chain.push((nw, nh, next));
    }
    chain
}

fn average(pixels: &[&[u8]], kind: TexelKind) -> [u8; 4] {
    let count = pixels.len() as f32;
    let mean =
        |c: usize, f: &dyn Fn(u8) -> f32| pixels.iter().map(|p| f(p[c])).sum::<f32>() / count;
    let unit = |b: u8| f32::from(b) / 255.0;
    match kind {
        TexelKind::Color => {
            let rgb = [0, 1, 2].map(|c| linear_to_srgb(mean(c, &srgb_to_linear)));
            [rgb[0], rgb[1], rgb[2], (mean(3, &unit) * 255.0 + 0.5) as u8]
        }
        TexelKind::Detail => {
            let n = glam::Vec3::from([0, 1, 2].map(|c| mean(c, &|b| unit(b) * 2.0 - 1.0)));
            let spread = 1.0 - n.length().min(1.0);
            let n = n.normalize_or(glam::Vec3::Z);
            let rough = (mean(3, &unit) + spread * 1.5).min(1.0);
            let rgb = n.to_array().map(|c| ((c * 0.5 + 0.5) * 255.0 + 0.5) as u8);
            [rgb[0], rgb[1], rgb[2], (rough * 255.0 + 0.5) as u8]
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn pixel(t: &TextureImage, x: u32, y: u32) -> [u8; 4] {
        let i = ((y * t.width + x) * 4) as usize;
        [t.rgba[i], t.rgba[i + 1], t.rgba[i + 2], t.rgba[i + 3]]
    }

    #[test]
    fn flat_material_has_no_texture() {
        let m = Material::flat([0.5, 0.5, 0.5, 1.0]);
        assert!(m.texture.is_none() && m.detail.is_none());
        assert_eq!(m.vertex_color(), [0.5, 0.5, 0.5, 1.0]);
    }

    #[test]
    fn every_weave_tiles_and_has_relief() {
        for texture in FabricTexture::ALL {
            let (albedo, detail) = weave(texture, [180, 160, 140], 10);
            assert_eq!((albedo.width, albedo.height), (SIZE, SIZE));
            assert_eq!(detail.rgba.len(), (SIZE * SIZE * 4) as usize);
            assert_eq!(detail.id, 11);
            assert!(albedo.rgba.chunks_exact(4).all(|p| p[3] == 255));
            // Normals point out of the surface and some lean.
            let leaning = detail
                .rgba
                .chunks_exact(4)
                .filter(|p| {
                    assert!(p[2] >= 128, "{texture:?} normal points in");
                    p[2] < 250
                })
                .count();
            assert!(leaning > 100, "{texture:?} is flat ({leaning})");
            // Seamless: the image's two edges are neighbours in the tiling,
            // so they differ no more than neighbours across the middle,
            // which is a repeat boundary too.
            let edge: i32 = (0..SIZE)
                .map(|y| {
                    let (a, b) = (pixel(&albedo, 0, y), pixel(&albedo, SIZE - 1, y));
                    (i32::from(a[0]) - i32::from(b[0])).abs()
                })
                .sum();
            let inside: i32 = (0..SIZE)
                .map(|y| {
                    let (a, b) = (pixel(&albedo, SIZE / 2 - 1, y), pixel(&albedo, SIZE / 2, y));
                    (i32::from(a[0]) - i32::from(b[0])).abs()
                })
                .sum();
            assert!(
                edge <= inside * 2 + 2 * SIZE as i32,
                "{texture:?}: {edge} vs {inside}"
            );
        }
    }

    #[test]
    fn twill_runs_diagonally_and_satin_is_smoother_than_plain() {
        // A 3/1 twill repeats one cell along the diagonal: a step across
        // and a step down lands on the same kind of float.
        let base = [0.2, 0.25, 0.5];
        let cell = 1.0 / 4.0;
        let at = |u: f32, v: f32| texel(FabricTexture::Twill, base, u, v).height;
        let (u, v) = (0.3 * cell, 0.5 * cell);
        assert!((at(u, v) - at(u + cell, v - cell)).abs() < 0.05);
        // Down the middle of a warp yarn, satin's long floats stay up
        // where plain weave dips at every crossing: per cell (5 to
        // satin's repeat, 2 to plain's), far fewer low samples.
        let low = |t: FabricTexture, u: f32| {
            (0..64)
                .filter(|k| texel(t, base, u, *k as f32 / 64.0).height < 0.6)
                .count()
        };
        let satin = low(FabricTexture::Satin, 0.1) as f32 / 5.0;
        let plain = low(FabricTexture::Plain, 0.25) as f32 / 2.0;
        assert!(satin * 2.0 < plain, "{satin} {plain}");
    }

    #[test]
    fn fabrics_get_their_look_and_share_textures() {
        let satin = for_fabric(&Fabric::satin());
        let velvet = for_fabric(&Fabric::velvet());
        let chiffon = for_fabric(&Fabric::chiffon());
        assert!(satin.surface.roughness < 0.3);
        assert!(velvet.surface.sheen.iter().any(|&s| s > 0.1));
        assert!(chiffon.surface.opacity < 0.5);
        assert_eq!(
            satin.repeat_mm,
            Fabric::satin().look.repeat_mm * REPEATS as f32
        );
        // The same weave and colour reuse one generated texture.
        let again = for_fabric(&Fabric::satin());
        assert!(Arc::ptr_eq(
            satin.texture.as_ref().unwrap(),
            again.texture.as_ref().unwrap()
        ));
        assert_ne!(
            satin.texture.as_ref().unwrap().id,
            velvet.texture.as_ref().unwrap().id
        );
        assert_eq!(satin.vertex_color(), [1.0, 1.0, 1.0, 1.0]);
    }

    #[test]
    fn mips_halve_down_to_one_pixel_and_rough_up_bumpy_detail() {
        let (_, detail) = weave(FabricTexture::Plain, [200, 200, 200], 0);
        let chain = mip_chain(detail.width, detail.height, &detail.rgba, TexelKind::Detail);
        assert_eq!(chain.len(), 9);
        assert_eq!((chain[8].0, chain[8].1), (1, 1));
        // At 1×1 the weave averages to a flat surface, rougher than its
        // average roughness scale.
        let last = &chain[8].2;
        assert!(last[2] > 245, "{last:?}");
        let mean_alpha = detail
            .rgba
            .chunks_exact(4)
            .map(|p| f32::from(p[3]))
            .sum::<f32>()
            / (SIZE * SIZE) as f32;
        assert!(f32::from(last[3]) > mean_alpha);
        // Colour averages in linear light: black and white make a mid grey
        // brighter than 128 in sRGB.
        let chain = mip_chain(2, 1, &[0, 0, 0, 255, 255, 255, 255, 255], TexelKind::Color);
        assert!(chain[1].2[0] > 180, "{:?}", chain[1].2);
    }

    #[test]
    fn photo_maps_raise_bright_threads() {
        // Vertical stripes: bright in the middle columns.
        let (w, h) = (8, 4);
        let rgba: Vec<u8> = (0..w * h)
            .flat_map(|i| {
                let v = if (2..6).contains(&(i % w)) { 230 } else { 30 };
                [v, v, v, 255]
            })
            .collect();
        let (albedo, detail) = maps_from_photo(5, w, h, &rgba);
        assert_eq!(albedo.rgba, rgba);
        assert_eq!(detail.id, 6);
        // Left of the bright stripe the surface leans left (−x), right of
        // it right: it's a ridge.
        assert!(pixel(&detail, 1, 1)[0] < 128);
        assert!(pixel(&detail, 6, 1)[0] > 128);
        // Bright is smoother than dark.
        assert!(pixel(&detail, 3, 1)[3] < pixel(&detail, 0, 1)[3]);
    }
}
